(40417, 218, 324, '<td valign="top">Gorgeous - the thumbnail doesn''t do it justice - extremely creative and original</td>', 'Gorgeous - the thumbnail doesn''t do it justice - extremely creative and original', '2002-03-12 14:43:00.000000', NULL, 1),
