(40747, 256, 261, '<td valign="top">nice photo.. professional looking</td>', 'nice photo.. professional looking', '2002-03-11 02:17:00.000000', NULL, 1),
(40748, 256, 459, '<td valign="top">Nice concept, but clutter takes away from central theme of picture.  What is the central theme?  Not the wine!  Maybe the candle</td>', 'Nice concept, but clutter takes away from central theme of picture.  What is the central theme?  Not the wine!  Maybe the candle', '2002-03-11 13:37:00.000000', NULL, 1),
(40749, 256, 542, '<td valign="top">I like red wines. But who eats roses with a wine?</td>', 'I like red wines. But who eats roses with a wine?', '2002-03-12 13:02:00.000000', NULL, 1),
(40750, 256, 549, '<td valign="top">no focal point, unless you count the candle and it''s not red. Looks more like a snapshot.</td>', 'no focal point, unless you count the candle and it''s not red. Looks more like a snapshot.', '2002-03-12 17:21:00.000000', NULL, 1),
(40751, 256, 543, '<td valign="top">Hmmm... I''m torn over this one.  Sharp, focused (rare around here it seems), properly exposed (WTG getting that candlelight), with lots of interesting elements.  Composition is a little busy, but that candle draws my eye to the hotspot, and there are interesting geometric relationships to lead one around.  I guess what bugs me is the chocolate smears.  Lame, I know, but a fresh plate and just the petals would be a big improvement IMO.</td>', 'Hmmm... I''m torn over this one.  Sharp, focused (rare around here it seems), properly exposed (WTG getting that candlelight), with lots of interesting elements.  Composition is a little busy, but that candle draws my eye to the hotspot, and there are interesting geometric relationships to lead one around.  I guess what bugs me is the chocolate smears.  Lame, I know, but a fresh plate and just the petals would be a big improvement IMO.', '2002-03-13 04:53:00.000000', NULL, 1),
(40752, 256, 113, '<td valign="top">The picture doesn''t do much for the title..... maybe -- Traces of Romance?</td>', 'The picture doesn''t do much for the title..... maybe -- Traces of Romance?', '2002-03-14 09:02:00.000000', NULL, 1),
(40753, 256, 49, '<td valign="top">nice setting</td>', 'nice setting', '2002-03-15 09:34:00.000000', NULL, 1),
(40754, 256, 324, '<td valign="top">Hmmm... looks like tasty preparation for this shot.  I didn''t really like this shot from the thumbnail, and at first glance didn''t like the original, but as I look at it for minute its really starting to grow on me - the warmth of the reds and the yellow candle (great action on the flame, by the way) are offset by the cool ambient light, which really makes you think of early evening, the cool air, and the butterflies-in-your-stomach feeling of the unknown excitement the night may offer.  The wine, empty dessert plate, and rose petals, as well as the obviously elegant setting enhance this feeling, and the photo really works well.  Congratulations on an excellent shot.</td>', 'Hmmm... looks like tasty preparation for this shot.  I didn''t really like this shot from the thumbnail, and at first glance didn''t like the original, but as I look at it for minute its really starting to grow on me - the warmth of the reds and the yellow candle (great action on the flame, by the way) are offset by the cool ambient light, which really makes you think of early evening, the cool air, and the butterflies-in-your-stomach feeling of the unknown excitement the night may offer.  The wine, empty dessert plate, and rose petals, as well as the obviously elegant setting enhance this feeling, and the photo really works well.  Congratulations on an excellent shot.', '2002-03-15 10:25:00.000000', NULL, 1),
(40755, 256, 210, '<td valign="top">Beautiful composition.  Definitely thought about what you wanted to do rather than take some snapshots of random red objects.  Nice.</td>', 'Beautiful composition.  Definitely thought about what you wanted to do rather than take some snapshots of random red objects.  Nice.', '2002-03-15 20:09:00.000000', NULL, 1),
(40756, 256, 577, '<td valign="top">a good photo</td>', 'a good photo', '2002-03-15 22:17:00.000000', NULL, 1),
(40757, 256, 564, '<td valign="top">VEry soft on the eye, bleeds of romanticism....very good!</td>', 'VEry soft on the eye, bleeds of romanticism....very good!', '2002-03-16 23:06:00.000000', NULL, 1),
